const normalized = ($item(0).$node['Set: Parse Typeform Response']?.json) || {};
const targetName = String(normalized.foundersBusinessName || '').trim();

if (!targetName) {
  return [{
    json: {
      ...normalized,
      found: false,
      // no id on purpose
      name: '',
      error: 'Missing founder business name'
    },
    pairedItem: 0
  }];
}


const items = $items(); // [{ json: { id, name, ... } }, ...]

let match = null;


for (const it of items) {
  const j = it.json ?? it;
  const n = String(j.name || '').trim();
  if (!n) continue;
  if (n.localeCompare(targetName, undefined, { sensitivity: 'accent' }) === 0) {
    match = j;
    break;
  }
}


if (!match) {
  const lower = targetName.toLowerCase();
  match = items.map(it => it.json ?? it)
               .find(j => String(j.name || '').toLowerCase().trim() === lower) || null;
}


const base = {
  ...normalized,
  found: !!match,
  name: targetName,
  listedCount: items.length
};

if (match && match.id) {
  base.id = match.id;
}

return [{ 
  json: base,
  pairedItem: 0 
}];
